python3 << 'EOF'
import json
import re

data = json.load(open('/app/resources/treasury_bulletin_1969_10.json'))
elements = data['document']['elements']

# Let's do a comprehensive search for debt tables with January data for all years
debt_data = {}

for i, elem in enumerate(elements):
    if 'content' in elem and elem['content']:
        content = str(elem['content'])

        # Look for table headers that indicate total debt outstanding
        if 'Total outstanding' in content and 'Agency securities' in content:
            # This is the main debt table
            # Find all rows with January data
            jan_patterns = re.findall(r'<tr><td>(\d{4}-January)</td><td>([\d,]+)</td><td>([\d,]+)</td><td>([\d,]+)</td>', content)
            for year, total, pub_debt, agency in jan_patterns:
                debt_data[year] = {'total': total, 'public_debt': pub_debt, 'agency': agency}
            print("Found debt data:", debt_data)

print("\nFinal debt data:")
for year in sorted(debt_data.keys()):
    print(f"{year}: {debt_data[year]}")
EOF

